הקוד שלמטה הוא אפליקציית **Task Manager** מלאה – ניהול משימות עם הוספה, עריכה, סימון כהושלמה, סינון, שמירה ב‑localStorage ו‑UI מודרני רספונסיבי. כל הקבצים משולבים בקובץ HTML יחיד, כך שהאפליקציה רצה מיד בתצוגה מקדימה.

```html
<!-- file: task-manager.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>Task Manager – BIRGSOL AI</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
:root {
 --clr-primary: #4a90e2;
 --clr-bg: #f5f7fa;
 --clr-card: #ffffff;
 --clr-text: #333333;
 --clr-muted: #777777;
 --radius: .8rem;
 --shadow: 0 4px 12px rgba(0,0,0,.08);
 --transition: .3s ease;
}
@media (prefers-color-scheme: dark) {
 :root {
 --clr-bg: #1e1e1e;
 --clr-card: #2c2c2c;
 --clr-text: #e0e0e0;
 --clr-muted: #aaaaaa;
 }
}
body {
 margin:0; font-family: system-ui, -apple-system, sans-serif;
 background: var(--clr-bg);
 color: var(--clr-text);
 display:flex; justify-content:center; align-items:flex-start;
 min-height:100vh; padding:2rem;
}
.container {
 width:100%; max-width:480px;
 background: var(--clr-card);
 border-radius: var(--radius);
 box-shadow: var(--shadow);
 overflow:hidden;
}
header {
 background: linear-gradient(135deg, var(--clr-primary), #6ab7ff);
 color:#fff; padding:1.2rem;
 text-align:center; font-size:1.4rem;
}
main { padding:1rem; }
form {
 display:flex; gap:.5rem; margin-bottom:1rem;
}
input[type="text"] {
 flex:1; padding:.6rem 1rem;
 border:1px solid #ccc; border-radius: var(--radius);
 font-size:1rem;
}
button {
 padding:.6rem 1rem; border:none; border-radius: var(--radius);
 background: var(--clr-primary); color:#fff;
 cursor:pointer; font-size:1rem;
 transition: var(--transition);
}
button:hover { background:#357ab8; }
.task-list { list-style:none; margin:0; padding:0; }
.task-item {
 display:flex; align-items:center; justify-content:space-between;
 padding:.8rem 1rem; border-bottom:1px solid #e0e0e0;
 transition: var(--transition);
}
.task-item:hover { background:#f0f8ff; }
.task-item.completed .title { text-decoration:line-through; color:var(--clr-muted); }
.title { flex:1; margin:0 .5rem; word-break:break-word; }
.actions button {
 background:transparent; color:var(--clr-muted);
 font-size:1.2rem; padding:.2rem;
}
.actions button:hover { color:var(--clr-primary); }
.filter-bar {
 display:flex; justify-content:center; gap:.5rem; margin-bottom:1rem;
}
.filter-bar button {
 background:transparent; color:var(--clr-muted);
 border:1px solid var(--clr-muted); border-radius: var(--radius);
 padding:.4rem .8rem;
}
.filter-bar button.active {
 background:var(--clr-primary); color:#fff; border-color:var(--clr-primary);
}
.empty-state {
 text-align:center; color:var(--clr-muted); padding:2rem 0;
}
@media (max-width: 480px) {
 header { font-size:1.2rem; }
}
</style>
</head>
<body>
<div class="container" aria-label="מנהל משימות">
 <header>מנהל משימות</header>
 <main>
 <form id="taskForm" aria-label="הוספת משימה חדשה">
 <input type="text" id="taskInput" placeholder="הכנס משימה..." aria-label="תיאור משימה">
 <button type="submit" aria-label="הוסף משימה">+</button>
 </form>

 <div class="filter-bar" role="group" aria-label="סינון משימות">
 <button data-filter="all" class="active">הכל</button>
 <button data-filter="active">פעילות</button>
 <button data-filter="completed">הושלמו</button>
 </div>

 <ul class="task-list" id="taskList" aria-live="polite"></ul>

 <div class="empty-state" id="emptyState" hidden>אין משימות כאן. הוסף משימה חדשה!</div>
 </main>
</div>

<script>
(() => {
 const STORAGE_KEY = 'birgsoll_tasks';
 const taskForm = document.getElementById('taskForm');
 const taskInput = document.getElementById('taskInput');
 const taskList = document.getElementById('taskList');
 const emptyState = document.getElementById('emptyState');
 const filterButtons = document.querySelectorAll('.filter-bar button');

 let tasks = [];
 let currentFilter = 'all';

 // ---------- אחסון ----------
 const loadTasks = () => {
 try {
 const data = localStorage.getItem(STORAGE_KEY);
 tasks = data ? JSON.parse(data) : [];
 } catch (e) {
 console.error('שגיאת קריאת משימות:', e);
 tasks = [];
 }
 };
 const saveTasks = () => {
 try {
 localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
 } catch (e) {
 console.error('שגיאת שמירת משימות:', e);
 }
 };

 // ---------- רינדור ----------
 const render = () => {
 taskList.innerHTML = '';
 const filtered = tasks.filter(t => {
 if (currentFilter === 'active') return !t.completed;
 if (currentFilter === 'completed') return t.completed;
 return true;
 });

 if (filtered.length === 0) {
 emptyState.hidden = false;
 } else {
 emptyState.hidden = true;
 filtered.forEach(task => {
 const li = document.createElement('li');
 li.className = 'task-item' + (task.completed ? ' completed' : '');
 li.setAttribute('data-id', task.id);

 const checkbox = document.createElement('input');
 checkbox.type = 'checkbox';
 checkbox.checked = task.completed;
 checkbox.setAttribute('aria-label', 'סמן כהושלמה');
 checkbox.addEventListener('change', toggleComplete);

 const title = document.createElement('span');
 title.className = 'title';
 title.textContent = task.text;

 const actions = document.createElement('div');
 actions.className = 'actions';

 const editBtn = document.createElement('button');
 editBtn.innerHTML = '✏️';
 editBtn.title = 'ערוך';
 editBtn.addEventListener('click', editTask);

 const delBtn = document.createElement('button');
 delBtn.innerHTML = '🗑️';
 delBtn.title = 'מחק';
 delBtn.addEventListener('click', deleteTask);

 actions.append(editBtn, delBtn);
 li.append(checkbox, title, actions);
 taskList.appendChild(li);
 });
 }
 };

 // ---------- פעולות ----------
 const addTask = (text) => {
 const newTask = {
 id: Date.now().toString(),
 text: text.trim(),
 completed: false,
 createdAt: new Date().toISOString()
 };
 tasks.unshift(newTask);
 saveTasks();
 render();
 };

 const toggleComplete = (e) => {
 const id = e.target.closest('li').dataset.id;
 const task = tasks.find(t => t.id === id);
 if (task) {
 task.completed = e.target.checked;
 saveTasks();
 render();
 }
 };

 const editTask = (e) => {
 const li = e.target.closest('li');
 const id = li.dataset.id;
 const task = tasks.find(t => t.id === id);
 if (!task) return;

 const newText = prompt('ערוך את המשימה:', task.text);
 if (newText !== null && newText.trim() !== '') {
 task.text = newText.trim();
 saveTasks();
 render();
 }
 };

 const deleteTask = (e) => {
 const li = e.target.closest('li');
 const id = li.dataset.id;
 tasks = tasks.filter(t => t.id !== id);
 saveTasks();
 render();
 };

 const setFilter = (filter) => {
 currentFilter = filter;
 filterButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.filter === filter));
 render();
 };

 // ---------- אירועי UI ----------
 taskForm.addEventListener('submit', (e) => {
 e.preventDefault();
 const text = taskInput.value;
 if (text.trim() === '') {
 alert('הכנס תיאור משימה');
 return;
 }
 addTask(text);
 taskInput.value = '';
 taskInput.focus();
 });

 filterButtons.forEach(btn => {
 btn.addEventListener('click', () => setFilter(btn.dataset.filter));
 });

 // ---------- אתחול ----------
 loadTasks();
 render();
})();
</script>
</body>
</html>
```

**מה האפליקציה עושה** 
- מאפשרת להוסיף, לערוך, למחוק ולסמן משימות כהושלמו. 
- מציגה סינון בין “הכל”, “פעילות” ו-“הושלמו”. 
- שומרת את כל המשימות ב‑localStorage, כך שהנתונים נשמרים גם אחרי רענון הדף. 

**איך אפשר להרחיב** 
- להוסיף תזכורות עם `Notification API`. 
- לשלב סינון לפי תאריך או תוויות. 
- להמיר ל‑PWA כך שהאפליקציה תעבוד גם אופליין מלא.
